doc.example:
try (Basalt jsl = Basalt.create()) {
    MultiheadAttention attention =
            new MultiheadAttention(basalt.context(), 64, 8, true, 0.1f, 7L);
    Tensor input = basalt.randn(2, 16, 64);
    attention.train();
    Tensor output = attention.forward(input);
    // output 形状为 [2, 16, 64]
    attention.eval();
    attention.close();
}
